  function loadState(){try{const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');return raw&&typeof raw==='object'?{...DEFAULT_STATE,...raw, favorites:Array.isArray(raw.favorites)?raw.favorites:DEFAULT_STATE.favorites,alarms:Array.isArray(raw.alarms)?raw.alarms:[]}:structuredClone(DEFAULT_STATE)}catch{return structuredClone(DEFAULT_STATE)}}
  function saveState(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch(e){console.warn('Could not persist ORBIT preferences',e)}}
  function toast(message, type=''){const region=$('#toast-region');const el=document.createElement('div');el.className='toast'+(type?' '+type:'');el.textContent=message;region.append(el);setTimeout(()=>el.remove(),3800)}
  function safeText(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
  function flagForCode(code){if(FLAG_FIX[code])return FLAG_FIX[code];if(/^[A-Z]{2}$/.test(code||''))return String.fromCodePoint(...[...code].map(ch=>0x1F1E6+ch.charCodeAt(0)-65));return '🌐'}
  function canonicalCountry(name){return NAME_ALIASES.get(name)||name||'Unknown region'}
  function cityCountryMatch(city,country){const a=canonicalCountry(city?.country).toLowerCase().trim(),b=canonicalCountry(country).toLowerCase().trim();return !!a&&!!b&&a===b}
  function formatParts(timestamp, timezone){return OrbitCore.formatParts(timestamp,timezone)}
  function formatClock(timestamp,timezone,options={}){return OrbitCore.formatClock(timestamp,timezone,{seconds:options.seconds??state.seconds,format:options.format??state.format})}
  function formatDate(timestamp,timezone,options={}){return OrbitCore.formatDate(timestamp,timezone,options)}
  function formatShortDate(timestamp,timezone){try{return new Intl.DateTimeFormat('en-US',{timeZone:timezone,weekday:'short',month:'short',day:'numeric'}).format(new Date(timestamp))}catch{return '—'}}
  function offsetMinutes(timestamp,timezone){try{return OrbitCore.offsetMinutes(timestamp,timezone)}catch{return null}}
  function offsetLabel(timestamp,timezone){return OrbitCore.offsetLabel(timestamp,timezone)}
  function zoneShortName(timestamp,timezone){try{return new Intl.DateTimeFormat('en-US',{timeZone:timezone,timeZoneName:'short'}).formatToParts(new Date(timestamp)).find(p=>p.type==='timeZoneName')?.value||timezone}catch{return timezone}}
