  function updateSearchResultsLive(){if($('#world-search').value.trim())renderSearch($('#world-search').value,true)}
  function updateQuickCities(now=Date.now()){const quick=['tokyo','london','new-york'].map(id=>CITY_BY_ID.get(id));$('#quick-city-list').innerHTML=quick.map(c=>`<button class="mini-city" data-city-id="${c.id}" aria-label="Explore ${c.name}"><span class="mini-city-flag">${flagForCode(c.cc)}</span><div><b>${safeText(c.name)}</b><small class="mono">${safeText(formatClock(now,c.tz,{seconds:false}))}</small></div></button>`).join('');$$('#quick-city-list [data-city-id]').forEach(b=>b.addEventListener('click',()=>selectCity(CITY_BY_ID.get(b.dataset.cityId))))}
  function addFavorite(id){if(!CITY_BY_ID.has(id))return;if(!state.favorites.includes(id)){state.favorites.push(id);saveState();renderCities();updateFavoriteCount();toast(`${CITY_BY_ID.get(id).name} added to your collection.`)}else toast('That city is already in your collection.');}
