  function renderCities(){const grid=$('#city-grid'),empty=$('#cities-empty');const favoriteCities=state.favorites.map(id=>CITY_BY_ID.get(id)).filter(Boolean);let list=exploreCountry?CITIES.filter(c=>cityCountryMatch(c,exploreCountry)):favoriteCities;if(cityFilter==='day')list=list.filter(c=>{const s=solarTimes(c);if(!s?.rise||!s?.set)return false;const h=getLocalHour(Date.now(),c.tz),rise=s.rise.hour,set=s.set.hour;return rise<set?h>=rise&&h<set:h>=rise||h<set});if(cityFilter==='night')list=list.filter(c=>{const s=solarTimes(c);if(!s?.rise||!s?.set)return false;const h=getLocalHour(Date.now(),c.tz),rise=s.rise.hour,set=s.set.hour;return !(rise<set?h>=rise&&h<set:h>=rise||h<set)});empty.hidden=!!list.length;grid.hidden=!list.length;grid.innerHTML=list.map(c=>cityCardHtml(c)).join('');grid.querySelectorAll('[data-favorite]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const id=b.dataset.favorite;if(state.favorites.includes(id))removeFavorite(id);else addFavorite(id)}));grid.querySelectorAll('[data-open-city]').forEach(el=>{el.addEventListener('click',e=>{if(e.target.closest('button,a'))return;selectCity(CITY_BY_ID.get(el.dataset.openCity))});el.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button,a')){e.preventDefault();selectCity(CITY_BY_ID.get(el.dataset.openCity))}})});loadCityThumbnails();if(exploreCountry){$('#cities-title').textContent=exploreCountry+' cities';$('.view-heading .section-copy').textContent='Explore supported city timezones in this country, then add favorites to your own collection.'}else{$('#cities-title').textContent='Cities, in sync.';$('.view-heading .section-copy').textContent='Keep your important places close, from sunrise meetings to midnight calls.'}updateFavoriteCount()}
  function cityCardHtml(c){const isSaved=state.favorites.includes(c.id),now=Date.now(),s=c.kind==='zone'?null:solarTimes(c),h=getLocalHour(now,c.tz),day=!!(s?.rise&&s?.set&&(s.rise.hour<s.set.hour?h>=s.rise.hour&&h<s.set.hour:h>=s.rise.hour||h<s.set.hour));return`<article class="city-card" data-open-city="${c.id}" tabindex="0" role="button" aria-label="Open ${safeText(c.name)}"><div class="city-card-hero" data-card-image="${c.id}"><div class="city-card-country">${c.kind==='zone'?'◷ · TIMEZONE REFERENCE':`${flagForCode(c.cc)} · ${safeText(c.country)}`}</div><div class="city-card-city">${safeText(c.name)}</div><button class="city-card-fav ${isSaved?'saved':''}" data-favorite="${c.id}" aria-label="${isSaved?'Remove':'Add'} ${safeText(c.name)} ${isSaved?'from':'to'} collection">${isSaved?'★':'☆'}</button></div><div class="city-card-body"><div class="city-card-time mono" data-clock-city="${c.id}">${safeText(formatClock(now,c.tz))}</div><div class="city-card-date" data-date-city="${c.id}">${safeText(formatDate(now,c.tz))}</div><div class="city-card-footer"><span>${safeText(offsetLabel(now,c.tz))}</span><b>${c.kind==='zone'?'IANA ZONE':day?'☼ DAY':'☾ NIGHT'}</b></div></div></article>`}
  function updateCityTimes(now=Date.now()){ $$('[data-clock-city]').forEach(el=>{const c=CITY_BY_ID.get(el.dataset.clockCity);if(c)el.textContent=formatClock(now,c.tz)});$$('[data-date-city]').forEach(el=>{const c=CITY_BY_ID.get(el.dataset.dateCity);if(c)el.textContent=formatDate(now,c.tz)});}
  async function fetchCityPhoto(city,width=1400){
    if(!city)return null;
    const cacheKey='orbit-photo-'+city.id;
    try{const cached=JSON.parse(sessionStorage.getItem(cacheKey)||'null');if(cached)return cached.none?null:cached}catch{}
    const query=`filetype:bitmap ${city.name} skyline`;
    const url='https://commons.wikimedia.org/w/api.php?'+new URLSearchParams({action:'query',generator:'search',gsrsearch:query,gsrnamespace:'6',gsrlimit:'12',prop:'imageinfo',iiprop:'url|extmetadata',iiurlwidth:String(width),format:'json',origin:'*'});
    const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),8000);
    try{
      const r=await fetch(url,{signal:controller.signal});if(!r.ok)throw new Error('Image source unavailable');const data=await r.json();const pages=Object.values(data.query?.pages||{});
      const normalized=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
      const cityTokens=normalized(city.name).split(/\s+/).filter(Boolean);
      const score=p=>{const t=normalized(p.title);return cityTokens.reduce((n,w)=>n+(t.split(' ').includes(w)?5:-10),0)+(t.includes('skyline')?6:0)+(t.includes('cityscape')?4:0)+(t.includes('downtown')?2:0)+(t.includes('aerial')?1:0)};
      pages.sort((a,b)=>score(b)-score(a));
      const best=pages.map(p=>{const info=p.imageinfo?.[0];const title=normalized(p.title);const hasPlace=cityTokens.every(w=>title.split(' ').includes(w));const visualWord=['skyline','cityscape','city','downtown','aerial','panorama','night'].some(w=>title.includes(w));return{name:p.title,info,good:hasPlace&&visualWord&&!!(info?.thumburl||info?.url)}}).find(x=>x.good);
      if(!best){try{sessionStorage.setItem(cacheKey,JSON.stringify({none:true}))}catch{}return null}
      const meta=best.info.extmetadata||{};const plain=s=>{const el=document.createElement('div');el.innerHTML=String(s||'');return(el.textContent||'').replace(/\s+/g,' ').trim()};const result={url:best.info.thumburl||best.info.url,title:best.name,credit:plain(meta.Artist?.value||meta.Credit?.value||'Wikimedia Commons contributor'),source:best.info.descriptionurl||'https://commons.wikimedia.org/'};
      try{sessionStorage.setItem(cacheKey,JSON.stringify(result))}catch{}return result;
    }finally{clearTimeout(timeout)}
  }
  async function loadSkyline(city){
    const token=++imageRequestToken,img=$('#skyline-image'),link=$('#skyline-source'),caption=$('#skyline-credit'),fallback=$('#skyline-fallback');img.hidden=true;img.removeAttribute('src');link.hidden=true;fallback.style.opacity='1';
    if(!city){caption.textContent='Illustrative visual · no city photograph';$('#image-kicker').textContent='ILLUSTRATIVE FALLBACK · NOT A PHOTO';return}if(city.kind==='zone'){caption.textContent='IANA timezone reference point · no city photograph';$('#image-kicker').textContent='TIMEZONE REFERENCE · NOT A CITY PHOTO';return}
    caption.textContent='LOOKING FOR A MATCHING CITY PHOTOGRAPH…';
    try{const result=await fetchCityPhoto(city,1400);if(token!==imageRequestToken)return;if(!result){caption.textContent='ILLUSTRATIVE CITYSCAPE · NO MATCHING PHOTO TITLE';$('#image-kicker').textContent='ILLUSTRATIVE FALLBACK · NOT A PHOTO';fallback.style.opacity='1';return}
      const candidate=new Image();candidate.onload=()=>{if(token!==imageRequestToken)return;img.src=result.url;img.alt=`Photograph associated with ${city.name}, ${city.country}. Wikimedia Commons file: ${result.title}`;img.hidden=false;fallback.style.opacity='.12';$('#image-kicker').textContent='WIKIMEDIA PHOTO · TITLE MATCH';caption.textContent=('PHOTO CREDIT · '+(result.credit||'Wikimedia Commons')).slice(0,74);caption.title=result.title+' — '+result.credit;link.href=result.source;link.title=`Open source and license details: ${result.title}`;link.hidden=false;};candidate.onerror=()=>{if(token===imageRequestToken){caption.textContent='ILLUSTRATIVE CITYSCAPE · PHOTO UNAVAILABLE';$('#image-kicker').textContent='ILLUSTRATIVE FALLBACK · NOT A PHOTO';fallback.style.opacity='1'}};candidate.src=result.url;
    }catch(e){if(token===imageRequestToken){caption.textContent='ILLUSTRATIVE CITYSCAPE · PHOTO SOURCE OFFLINE';$('#image-kicker').textContent='ILLUSTRATIVE FALLBACK · NOT A PHOTO';fallback.style.opacity='1'}}
  }
